<?php

namespace Bga\Games\RegroupChickenArmy\States;

use Bga\Games\RegroupChickenArmy\Components\Boards;
use Bga\Games\RegroupChickenArmy\Game;
use BgaUserException;
use Bga\Games\RegroupChickenArmy\Components\Market;
use Bga\Games\RegroupChickenArmy\Components\Resources;
use BgaVisibleSystemException;

class PlayerTurnStateHandler implements StateHandlerInterface
{
    /* AUTOGENERATED_HANDLE_START - DO NOT REMOVE THIS COMMENT */
    public static function handle(Game $game, string $action, ...$args): void
    {
        switch ($action) {
            case 'pickDeckCard':
                self::pickDeckCard($game);
                break;
            case 'putCard':
                self::putCard($game, $args[0], $args[1], $args[2], $args[3]);
                break;
            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
    /* AUTOGENERATED_HANDLE_END - DO NOT REMOVE THIS COMMENT */

    /* AUTOGENERATED_METHOD - putCard */
    private static function putCard(Game $game, int $cardId, int $rotation, int $posX, int $posY): void
    {
        $playerId = (int) $game->getCurrentPlayerId();
        $leaderId = (int) $game->getUniqueValueFromDB("SELECT leader_id FROM player WHERE player_id = $playerId");
        
        // Check if player is using a card from the deck
        $deckCardId = $game->getUniqueValueFromDB("SELECT marketCardPicked FROM player WHERE player_id = $playerId");
        if ($deckCardId !== null) {
            // Player is using a deck card
            if ($cardId != $deckCardId) {
                throw new BgaUserException(clienttranslate("You must use the card you picked from the deck"));
            }
            
            // Place the card on the player's board
            Boards::putCardOnBoard($game, $leaderId, $cardId, $rotation, $posX, $posY);
            
            // Clear the picked card
            $game->DbQuery("UPDATE player SET marketCardPicked = NULL WHERE player_id = $playerId");
            
            // Update resources based on the new card

            Resources::updateResourcesFromBoard($game, $leaderId);
            
            $game->gamestate->nextState("turnEnded");
            return;
        }
        
        // Player is using a market card
        $marketCards = Market::getAllMarketCards($game);
        $cardFound = false;
        $cardCost = 0;
        
        foreach ($marketCards as $index => $marketCard) {
            if ($marketCard['card_id'] == $cardId) {
                $cardFound = true;
                $cardCost = $index;
                break;
            }
        }
        
        if (!$cardFound) {
            throw new BgaUserException(clienttranslate("This card is not available in the market"));
        }
        
        // Check if player has enough coins
        $playerCoins = $game->getUniqueValueFromDB(
            "SELECT coin FROM resources WHERE leader_id = $leaderId"
        );
        
        if ($playerCoins < $cardCost) {
            throw new BgaUserException(clienttranslate("You don't have enough coins to buy this card"));
        }
        
        // Place the card on the player's board
        Boards::putCardOnBoard($game, $leaderId, $cardId, $rotation, $posX, $posY);

        Market::removeMarketCard($game, $cardId);
        
        // Update resources based on the new card
        Resources::updateResourcesFromBoard($game, $leaderId);
        
        $game->gamestate->nextState("turnEnded");
    }

    /* AUTOGENERATED_METHOD - pickDeckCard */
    private static function pickDeckCard(Game $game): void
    {
        $playerId = (int) $game->getCurrentPlayerId();

        $hasAlreadyPickADeckCard = $game->getUniqueValueFromDB(
            "SELECT `marketCardPicked` FROM `player` WHERE `player_id` = $playerId"
        );

        if ($hasAlreadyPickADeckCard != null) {
            $game->gamestate->nextState('retry');
            throw new BgaUserException(clienttranslate("You alreay had picked a deck card!"));
        }
        $deckCardId = Market::getMarketCard($game, 3);

        $game->DbQuery("UPDATE player SET marketCardPicked = $deckCardId WHERE player_id = $playerId");

        $game->notifyAllPlayers('deckCardPicked', clienttranslate('${player_name} picked a card from the deck.'), [
            'player_name' => $game->getActivePlayerName(),
            'player_id' => $playerId,
            'card_id' => $deckCardId
        ]);

        $game->gamestate->nextState("deckCardPicked");
    }

    public static function executeGameState(Game $game): void
    {
        $currentRound = $game->getGameStateValue('round');
        $expectedCardCount = $currentRound + 1; // +1 for the initial card
               
        // Get the count of cards placed by each player
        $cardCounts = $game->getCollectionFromDB(
            "SELECT p.player_id, COUNT(bm.movement_id) as card_count 
             FROM player p 
             LEFT JOIN boards_moves bm ON p.leader_id = bm.board_id 
             GROUP BY p.player_id"
        );
        
        // Check if all players have the expected number of cards
        $allPlayersReachedTarget = true;
        
        foreach ($cardCounts as $playerId => $data) {
            $count = (int) $data['card_count'];
            
            if ($count != $expectedCardCount) {
                $allPlayersReachedTarget = false;
                break;
            }
        }

        Market::getAllMarketCards($game);

        $marketCards = Market::getAllMarketCards($game);

        $game->notifyAllPlayers("marketUpdate", clienttranslate("The Market has been updated"), [
            "cards" => $marketCards
        ]);
        
        // If all players have reached the expected card count, transition to attack phase
        // Otherwise, go to next player
        if ($allPlayersReachedTarget) {
            $game->gamestate->nextState('startAtkPhase');
        } else {
            $currentPlayerId = $game->getCurrentPlayerId();
            $game->giveExtraTime($currentPlayerId);
            $game->activeNextPlayer();
            $game->gamestate->nextState('nextPlayer');
        }
    }
}




